  $orgchezzjs${"slug": "organic-chemistry", "title": "Organic Chemistry", "description": "A mechanism-centered course on organic structure, bonding, stereochemistry, acids and bases, substitution, elimination, addition, aromaticity, carbonyl chemistry, biomolecules, spectroscopy, synthesis, and lab reasoning.", "topics": [{"id": "4ef1c96b-9d9b-4f94-a746-da3fd4cf185a", "type": "topic", "title": "Structure and bonding", "description": "This module establishes structure and bonding as the course's first working framework. It supplies the language and representations needed before the path advances to acid–base and mechanism language.", "children": [{"id": "a3a28221-ac92-4e2c-b2b3-265ae1a3adcd", "type": "subtopic", "title": "Orbitals", "children": [], "description": "Orbitals identifies a specific object, distinction, or relationship within structure and bonding. Learners need to recognize and use it before combining this module's ideas in later work. It appears before resonance because that next topic assumes this starting point."}, {"id": "235c9866-bd3e-4c97-9f1b-4190295f99dc", "type": "subtopic", "title": "Resonance", "children": [], "description": "Resonance identifies a specific object, distinction, or relationship within structure and bonding. Learners need to recognize and use it before combining this module's ideas in later work. After orbitals, resonance supplies what is needed to address aromaticity preview."}, {"id": "7dec248b-97cc-41dc-bade-b134d557474c", "type": "subtopic", "title": "Aromaticity preview", "children": [], "description": "Aromaticity preview identifies a specific object, distinction, or relationship within structure and bonding. Learners need to recognize and use it before combining this module's ideas in later work. After resonance, aromaticity preview supplies what is needed to address conformations."}, {"id": "ccaabc8a-6fe1-49a1-9b0f-bdac55096686", "type": "subtopic", "title": "Conformations", "children": [], "description": "Conformations identifies a specific object, distinction, or relationship within structure and bonding. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, conformations carries the completed idea into acid–base and mechanism language."}]}, {"id": "1a3020ca-790e-4488-8e82-dcc3d65aba5c", "type": "topic", "title": "Acid–base and mechanism language", "description": "This module builds directly on structure and bonding and develops acid–base and mechanism language. It belongs here because its methods and distinctions are prerequisites for stereochemistry.", "children": [{"id": "913e3d4e-550e-4a40-8db6-de58ae836a55", "type": "subtopic", "title": "PKa", "children": [], "description": "PKa identifies a specific object, distinction, or relationship within acid–base and mechanism language. Learners need to recognize and use it before combining this module's ideas in later work. It appears before nucleophiles/electrophiles because that next topic assumes this starting point."}, {"id": "57af3782-347a-405f-a8f4-ff6e021e02df", "type": "subtopic", "title": "Nucleophiles/electrophiles", "children": [], "description": "Nucleophiles/electrophiles identifies a specific object, distinction, or relationship within acid–base and mechanism language. Learners need to recognize and use it before combining this module's ideas in later work. After pka, nucleophiles/electrophiles supplies what is needed to address energy diagrams."}, {"id": "88a7e691-c4ea-409e-9e6d-ccc7d0bf0fef", "type": "subtopic", "title": "Energy diagrams", "children": [], "description": "Energy diagrams gives acid–base and mechanism language a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After nucleophiles/electrophiles, energy diagrams supplies what is needed to address arrows."}, {"id": "02bbebac-afbb-4596-b4d6-7abd2e7295e3", "type": "subtopic", "title": "Arrows", "children": [], "description": "Arrows identifies a specific object, distinction, or relationship within acid–base and mechanism language. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, arrows carries the completed idea into stereochemistry."}]}, {"id": "0beb12fd-1b6f-4120-ab29-b6d301760cf8", "type": "topic", "title": "Stereochemistry", "description": "This module builds directly on acid–base and mechanism language and develops stereochemistry. It belongs here because its methods and distinctions are prerequisites for substitution and elimination.", "children": [{"id": "035b3753-6cf7-42d6-a4c1-d2c7464d5039", "type": "subtopic", "title": "Chirality", "children": [], "description": "Chirality identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module's ideas in later work. It appears before r/s and e/z because that next topic assumes this starting point."}, {"id": "a5de1b87-3cbc-4afa-9096-5fd88cb1883a", "type": "subtopic", "title": "R/S and E/Z", "children": [], "description": "R/S and E/Z identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module's ideas in later work. After chirality, r/s and e/z supplies what is needed to address conformational analysis."}, {"id": "7dd4610c-b6e4-482d-8549-df78f62815f7", "type": "subtopic", "title": "Conformational analysis", "children": [], "description": "Conformational analysis identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module's ideas in later work. After r/s and e/z, conformational analysis supplies what is needed to address stereoselectivity."}, {"id": "86873dd0-bc37-44c1-9129-20c6f0bb303d", "type": "subtopic", "title": "Stereoselectivity", "children": [], "description": "Stereoselectivity identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, stereoselectivity carries the completed idea into substitution and elimination."}]}, {"id": "cd278473-dc0c-4847-aee2-a4f78b588c7b", "type": "topic", "title": "Substitution and elimination", "description": "This module builds directly on stereochemistry and develops substitution and elimination. It belongs here because its methods and distinctions are prerequisites for alkenes and alkynes.", "children": [{"id": "72502628-57fe-4802-8d21-ea8875a8212f", "type": "subtopic", "title": "SN1/SN2/E1/E2", "children": [], "description": "SN1/SN2/E1/E2 identifies a specific object, distinction, or relationship within substitution and elimination. Learners need to recognize and use it before combining this module's ideas in later work. It appears before competition because that next topic assumes this starting point."}, {"id": "fa33914e-b870-45dc-a97f-fa34e0e43c6a", "type": "subtopic", "title": "Competition", "children": [], "description": "Competition identifies a specific object, distinction, or relationship within substitution and elimination. Learners need to recognize and use it before combining this module's ideas in later work. After sn1/sn2/e1/e2, competition supplies what is needed to address solvent and substrate effects."}, {"id": "bcd0d662-a939-40fd-80d3-11a907ec06c4", "type": "subtopic", "title": "Solvent and substrate effects", "children": [], "description": "Solvent and substrate effects identifies a specific object, distinction, or relationship within substitution and elimination. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, solvent and substrate effects carries the completed idea into alkenes and alkynes."}]}, {"id": "56c305f2-dea6-4ea9-8064-126ab2974074", "type": "topic", "title": "Alkenes and alkynes", "description": "This module builds directly on substitution and elimination and develops alkenes and alkynes. It belongs here because its methods and distinctions are prerequisites for spectroscopic identification.", "children": [{"id": "cfb97f8d-edad-46e1-bbd2-c39435270bd8", "type": "subtopic", "title": "Additions", "children": [], "description": "Additions supplies the causal sequence within alkenes and alkynes, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. It appears before regiochemistry because that next topic assumes this starting point."}, {"id": "0717e02f-cca4-4142-99be-d9f8fbafb82a", "type": "subtopic", "title": "Regiochemistry", "children": [], "description": "Regiochemistry identifies a specific object, distinction, or relationship within alkenes and alkynes. Learners need to recognize and use it before combining this module's ideas in later work. After additions, regiochemistry supplies what is needed to address oxidation/reduction."}, {"id": "561e2da1-75d8-4488-b934-53222c1d4d37", "type": "subtopic", "title": "Oxidation/reduction", "children": [], "description": "Oxidation/reduction supplies the causal sequence within alkenes and alkynes, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After regiochemistry, oxidation/reduction supplies what is needed to address synthesis."}, {"id": "e98e0d4c-244f-4ec7-a6fc-524efec363f9", "type": "subtopic", "title": "Synthesis", "children": [], "description": "Synthesis turns the theory of alkenes and alkynes into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. As the final topic in this module, synthesis carries the completed idea into spectroscopic identification."}]}, {"id": "475a25c0-8366-41ea-9c80-b63c1afc878d", "type": "topic", "title": "Spectroscopic identification", "description": "This module builds directly on alkenes and alkynes and develops spectroscopic identification. It belongs here because its methods and distinctions are prerequisites for aromatic chemistry.", "children": [{"id": "6bceb7d3-2098-4d65-89f2-5031dc1f4270", "type": "subtopic", "title": "IR", "children": [], "description": "IR identifies a specific object, distinction, or relationship within spectroscopic identification. Learners need to recognize and use it before combining this module's ideas in later work. It appears before 1h/13c nmr because that next topic assumes this starting point."}, {"id": "9488e415-fe29-4c70-a5d1-aba6879a0505", "type": "subtopic", "title": "1H/13C NMR", "children": [], "description": "1H/13C NMR identifies a specific object, distinction, or relationship within spectroscopic identification. Learners need to recognize and use it before combining this module's ideas in later work. After ir, 1h/13c nmr supplies what is needed to address mass spectrometry."}, {"id": "7c9c8e8a-e68f-42a9-85fe-c4a1f5c800a1", "type": "subtopic", "title": "Mass spectrometry", "children": [], "description": "Mass spectrometry connects spectroscopic identification to observable evidence and defines what a valid measurement or interpretation must support. After 1h/13c nmr, mass spectrometry supplies what is needed to address structure solving."}, {"id": "97317b4e-62be-4d17-b7e6-48e8aa2b795d", "type": "subtopic", "title": "Structure solving", "children": [], "description": "Structure solving identifies a specific object, distinction, or relationship within spectroscopic identification. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, structure solving carries the completed idea into aromatic chemistry."}]}, {"id": "0f0d211e-2693-4ca7-8f9e-77564c355ef2", "type": "topic", "title": "Aromatic chemistry", "description": "This module builds directly on spectroscopic identification and develops aromatic chemistry. It belongs here because its methods and distinctions are prerequisites for alcohols, ethers, and epoxides.", "children": [{"id": "f3688292-7557-4096-931a-7e1e3e719e0b", "type": "subtopic", "title": "Aromaticity", "children": [], "description": "Aromaticity identifies a specific object, distinction, or relationship within aromatic chemistry. Learners need to recognize and use it before combining this module's ideas in later work. It appears before electrophilic substitution because that next topic assumes this starting point."}, {"id": "4e0cd727-3726-432d-aba1-770e52627f99", "type": "subtopic", "title": "Electrophilic substitution", "children": [], "description": "Electrophilic substitution supplies the causal sequence within aromatic chemistry, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After aromaticity, electrophilic substitution supplies what is needed to address directing effects."}, {"id": "2a352dc6-2957-4c9f-b9b0-398d2dfef1a5", "type": "subtopic", "title": "Directing effects", "children": [], "description": "Directing effects identifies a specific object, distinction, or relationship within aromatic chemistry. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, directing effects carries the completed idea into alcohols, ethers, and epoxides."}]}, {"id": "16aebc54-7e0c-4ab3-acb0-58cd3b374de1", "type": "topic", "title": "Alcohols, ethers, and epoxides", "description": "This module builds directly on aromatic chemistry and develops alcohols, ethers, and epoxides. It belongs here because its methods and distinctions are prerequisites for carbonyl chemistry i.", "children": [{"id": "87255aa9-4133-4a9e-a5d3-222c66da4e2b", "type": "subtopic", "title": "Preparation", "children": [], "description": "Preparation identifies a specific object, distinction, or relationship within alcohols, ethers, and epoxides. Learners need to recognize and use it before combining this module's ideas in later work. It appears before activation because that next topic assumes this starting point."}, {"id": "3b16f97f-d617-4329-b7bb-d4adb8bfb70c", "type": "subtopic", "title": "Activation", "children": [], "description": "Activation identifies a specific object, distinction, or relationship within alcohols, ethers, and epoxides. Learners need to recognize and use it before combining this module's ideas in later work. After preparation, activation supplies what is needed to address ring opening."}, {"id": "f93d7542-9c03-4338-b967-9e076ee19d77", "type": "subtopic", "title": "Ring opening", "children": [], "description": "Ring opening identifies a specific object, distinction, or relationship within alcohols, ethers, and epoxides. Learners need to recognize and use it before combining this module's ideas in later work. After activation, ring opening supplies what is needed to address protecting groups."}, {"id": "84f4a695-b00a-4d9c-9612-57bd2def4aff", "type": "subtopic", "title": "Protecting groups", "children": [], "description": "Protecting groups identifies a specific object, distinction, or relationship within alcohols, ethers, and epoxides. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, protecting groups carries the completed idea into carbonyl chemistry i."}]}, {"id": "f7c9971b-1283-41dd-aefa-8e31bfd3e733", "type": "topic", "title": "Carbonyl chemistry I", "description": "This module builds directly on alcohols, ethers, and epoxides and develops carbonyl chemistry i. It belongs here because its methods and distinctions are prerequisites for carbonyl chemistry ii.", "children": [{"id": "8bc7d1bb-d66a-4d4e-82f7-52da3b691f70", "type": "subtopic", "title": "Aldehydes/ketones", "children": [], "description": "Aldehydes/ketones identifies a specific object, distinction, or relationship within carbonyl chemistry i. Learners need to recognize and use it before combining this module's ideas in later work. It appears before nucleophilic addition because that next topic assumes this starting point."}, {"id": "ec2a722e-e480-4128-822f-4c93971bc03b", "type": "subtopic", "title": "Nucleophilic addition", "children": [], "description": "Nucleophilic addition supplies the causal sequence within carbonyl chemistry i, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After aldehydes/ketones, nucleophilic addition supplies what is needed to address acetals."}, {"id": "a673482f-7bb7-4b44-bfb1-7998569a6156", "type": "subtopic", "title": "Acetals", "children": [], "description": "Acetals identifies a specific object, distinction, or relationship within carbonyl chemistry i. Learners need to recognize and use it before combining this module's ideas in later work. After nucleophilic addition, acetals supplies what is needed to address imines."}, {"id": "2720c19b-3e9c-442d-9c68-789ed06f1f51", "type": "subtopic", "title": "Imines", "children": [], "description": "Imines identifies a specific object, distinction, or relationship within carbonyl chemistry i. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, imines carries the completed idea into carbonyl chemistry ii."}]}, {"id": "60f281d7-fc8c-4cd7-b957-0f9c0af471f1", "type": "topic", "title": "Carbonyl chemistry II", "description": "This module builds directly on carbonyl chemistry i and develops carbonyl chemistry ii. It belongs here because its methods and distinctions are prerequisites for carboxylic acid derivatives.", "children": [{"id": "62c784e5-fb8f-46ca-8277-49d30115260b", "type": "subtopic", "title": "Enols/enolates", "children": [], "description": "Enols/enolates identifies a specific object, distinction, or relationship within carbonyl chemistry ii. Learners need to recognize and use it before combining this module's ideas in later work. It appears before aldol because that next topic assumes this starting point."}, {"id": "14e487f1-a345-4b07-8bbd-799316e3661e", "type": "subtopic", "title": "Aldol", "children": [], "description": "Aldol identifies a specific object, distinction, or relationship within carbonyl chemistry ii. Learners need to recognize and use it before combining this module's ideas in later work. After enols/enolates, aldol supplies what is needed to address conjugate addition."}, {"id": "3bdc475b-9f2b-4315-8cc8-b8b31b9cdb23", "type": "subtopic", "title": "Conjugate addition", "children": [], "description": "Conjugate addition supplies the causal sequence within carbonyl chemistry ii, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After aldol, conjugate addition supplies what is needed to address selectivity."}, {"id": "48923b36-0bb3-4b9c-9173-c1a4fbbc9725", "type": "subtopic", "title": "Selectivity", "children": [], "description": "Selectivity identifies a specific object, distinction, or relationship within carbonyl chemistry ii. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, selectivity carries the completed idea into carboxylic acid derivatives."}]}, {"id": "1067520a-d5b2-4bb7-898f-a2341fdb03be", "type": "topic", "title": "Carboxylic acid derivatives", "description": "This module builds directly on carbonyl chemistry ii and develops carboxylic acid derivatives. It belongs here because its methods and distinctions are prerequisites for synthesis and bio-organic integration.", "children": [{"id": "0ab1dafb-1420-460f-af29-c0549d967f02", "type": "subtopic", "title": "Acyl substitution", "children": [], "description": "Acyl substitution supplies the causal sequence within carboxylic acid derivatives, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. It appears before reactivity ladder because that next topic assumes this starting point."}, {"id": "51df790f-b772-4397-8633-4d06234cc9d8", "type": "subtopic", "title": "Reactivity ladder", "children": [], "description": "Reactivity ladder identifies a specific object, distinction, or relationship within carboxylic acid derivatives. Learners need to recognize and use it before combining this module's ideas in later work. After acyl substitution, reactivity ladder supplies what is needed to address condensation."}, {"id": "5a7f357c-be18-433f-a4ba-21bb00fc7a5f", "type": "subtopic", "title": "Condensation", "children": [], "description": "Condensation identifies a specific object, distinction, or relationship within carboxylic acid derivatives. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, condensation carries the completed idea into synthesis and bio-organic integration."}]}, {"id": "4414deb5-acf8-4ef0-8509-352dd8005811", "type": "topic", "title": "Synthesis and bio-organic integration", "description": "This culminating module draws on carboxylic acid derivatives and develops synthesis and bio-organic integration. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.", "children": [{"id": "eeca8bc5-39b2-4431-85db-d45f207c9545", "type": "subtopic", "title": "Amines", "children": [], "description": "Amines identifies a specific object, distinction, or relationship within synthesis and bio-organic integration. Learners need to recognize and use it before combining this module's ideas in later work. It appears before carbohydrates because that next topic assumes this starting point."}, {"id": "35c8c355-c1c2-4767-a395-e97663913130", "type": "subtopic", "title": "Carbohydrates", "children": [], "description": "Carbohydrates identifies a specific object, distinction, or relationship within synthesis and bio-organic integration. Learners need to recognize and use it before combining this module's ideas in later work. After amines, carbohydrates supplies what is needed to address peptides."}, {"id": "63429140-98a8-4f69-bd3d-99b329452d98", "type": "subtopic", "title": "Peptides", "children": [], "description": "Peptides identifies a specific object, distinction, or relationship within synthesis and bio-organic integration. Learners need to recognize and use it before combining this module's ideas in later work. After carbohydrates, peptides supplies what is needed to address retrosynthesis."}, {"id": "df12eca9-178f-4dfa-b482-80392d5ee566", "type": "subtopic", "title": "Retrosynthesis", "children": [], "description": "Retrosynthesis turns the theory of synthesis and bio-organic integration into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. As the final course topic, retrosynthesis requires ideas from the complete path to be integrated and transferred."}]}], "dbBacked": true}$orgchezzjs$::jsonb,
